  "services.tag.brandid": { en: "Brand Identity", de: "Markenidentität", fr: "Identité de marque", es: "Identidad de marca", it: "Identità del marchio", pt: "Identidade de marca", nl: "Merkidentiteit", tr: "Marka Kimliği", ar: "هوية العلامة التجارية", zh: "品牌标识" },
  "services.tag.visualdesign": { en: "Visual Design", de: "Visuelles Design", fr: "Design visuel", es: "Diseño visual", it: "Design visivo", pt: "Design visual", nl: "Visueel ontwerp", tr: "Görsel Tasarım", ar: "التصميم المرئي", zh: "视觉设计" },
  "services.tag.strategy": { en: "Strategy", de: "Strategie", fr: "Stratégie", es: "Estrategia", it: "Strategia", pt: "Estratégia", nl: "Strategie", tr: "Strateji", ar: "استراتيجية", zh: "战略" },
