  "selectedwork.web.desc": { en: "High-converting corporate websites designed to establish credibility and elevate digital presence.", de: "Konversionsstarke Unternehmenswebsites, die Glaubwürdigkeit schaffen und die digitale Präsenz steigern.", fr: "Sites web d'entreprise à forte conversion conçus pour établir la crédibilité et élever la présence numérique.", es: "Sitios web corporativos de alta conversión diseñados para establecer credibilidad y elevar la presencia digital.", it: "Siti web aziendali ad alta conversione progettati per stabilire credibilità ed elevare la presenza digitale.", pt: "Sites corporativos de alta conversão projetados para estabelecer credibilidade e elevar a presença digital.", nl: "Hoogconverterende bedrijfswebsites ontworpen om geloofwaardigheid te vestigen en digitale aanwezigheid te verhogen.", tr: "Güvenilirlik oluşturmak ve dijital varlığı yükseltmek için tasarlanmış yüksek dönüşümlü kurumsal web siteleri.", ar: "مواقع شركات عالية التحويل مصممة لبناء المصداقية ورفع الحضور الرقمي.", zh: "高转化企业网站，旨在建立信誉并提升数字存在。" },
  "selectedwork.startup": { en: "Startup Technology Ecosystems", de: "Startup-Technologie-Ökosysteme", fr: "Écosystèmes Technologiques Startup", es: "Ecosistemas Tecnológicos para Startups", it: "Ecosistemi Tecnologici per Startup", pt: "Ecossistemas Tecnológicos para Startups", nl: "Startup Technologie-ecosystemen", tr: "Startup Teknoloji Ekosistemleri", ar: "أنظمة تقنية للشركات الناشئة", zh: "初创技术生态系统" },
