  "clients.heading1": { en: "Who We", de: "Mit Wem Wir", fr: "Avec Qui Nous", es: "Con Quién", it: "Con Chi", pt: "Com Quem", nl: "Met Wie Wij", tr: "Kimlerle", ar: "مع من", zh: "我们与谁" },
