  "newsletter.badge": { en: "Stay Connected", de: "Bleiben Sie verbunden", fr: "Restez connecté", es: "Manténgase conectado", it: "Resta connesso", pt: "Fique conectado", nl: "Blijf verbonden", tr: "Bağlantıda kalın", ar: "ابقَ متصلاً", zh: "保持联系" },
  "newsletter.heading": { en: "Join the Denarixx Network", de: "Treten Sie dem Denarixx-Netzwerk bei", fr: "Rejoignez le réseau Denarixx", es: "Únase a la red Denarixx", it: "Unisciti alla rete Denarixx", pt: "Junte-se à rede Denarixx", nl: "Word lid van het Denarixx-netwerk", tr: "Denarixx Ağına Katılın", ar: "انضم إلى شبكة Denarixx", zh: "加入 Denarixx 网络" },
  "newsletter.text": { en: "Get updates on AI systems, digital innovation, product concepts, and future Denarixx developments.", de: "Erhalten Sie Updates zu KI-Systemen, digitaler Innovation, Produktkonzepten und zukünftigen Denarixx-Entwicklungen.", fr: "Recevez des mises à jour sur les systèmes d'IA, l'innovation numérique, les concepts de produits et les développements futurs de Denarixx.", es: "Reciba actualizaciones sobre sistemas de IA, innovación digital, conceptos de productos y futuros desarrollos de Denarixx.", it: "Ricevi aggiornamenti su sistemi di IA, innovazione digitale, concetti di prodotto e sviluppi futuri di Denarixx.", pt: "Receba atualizações sobre sistemas de IA, inovação digital, conceitos de produtos e futuros desenvolvimentos da Denarixx.", nl: "Ontvang updates over AI-systemen, digitale innovatie, productconcepten en toekomstige Denarixx-ontwikkelingen.", tr: "Yapay zeka sistemleri, dijital inovasyon, ürün konseptleri ve gelecekteki Denarixx gelişmeleri hakkında güncellemeler alın.", ar: "احصل على تحديثات حول أنظمة الذكاء الاصطناعي والابتكار الرقمي ومفاهيم المنتجات وتطورات Denarixx المستقبلية.", zh: "获取有关AI系统、数字创新、产品概念和未来Denarixx发展的更新。" },
  "newsletter.subscribe": { en: "Subscribe", de: "Abonnieren", fr: "S'abonner", es: "Suscribirse", it: "Iscriviti", pt: "Inscrever-se", nl: "Abonneren", tr: "Abone ol", ar: "اشترك", zh: "订阅" },
  "newsletter.thanks": { en: "Thank you for subscribing!", de: "Vielen Dank für Ihr Abonnement!", fr: "Merci pour votre abonnement !", es: "¡Gracias por suscribirse!", it: "Grazie per l'iscrizione!", pt: "Obrigado por se inscrever!", nl: "Bedankt voor uw abonnement!", tr: "Abone olduğunuz için teşekkürler!", ar: "شكراً لاشتراكك!", zh: "感谢您的订阅！" },

  "cta.badge": { en: "Ready to Get Started?", de: "Bereit loszulegen?", fr: "Prêt à commencer ?", es: "¿Listo para empezar?", it: "Pronti per iniziare?", pt: "Pronto para começar?", nl: "Klaar om te beginnen?", tr: "Başlamaya hazır mısınız?", ar: "مستعد للبدء؟", zh: "准备好开始了吗？" },

  "whatis.badge": { en: "What is Denarixx?", de: "Was ist Denarixx?", fr: "Qu'est-ce que Denarixx ?", es: "¿Qué es Denarixx?", it: "Che cos'è Denarixx?", pt: "O que é a Denarixx?", nl: "Wat is Denarixx?", tr: "Denarixx nedir?", ar: "ما هي Denarixx؟", zh: "Denarixx 是什么？" },
  "whatis.heading1": { en: "What", de: "Was", fr: "Ce que", es: "Qué", it: "Che cosa", pt: "O que", nl: "Wat", tr: "Denarixx", ar: "ما", zh: "什么是" },
  "whatis.heading2": { en: "Denarixx Is", de: "Denarixx ist", fr: "Denarixx Est", es: "Es Denarixx", it: "È Denarixx", pt: "é a Denarixx", nl: "Denarixx is", tr: "Denarixx'tir", ar: "هي Denarixx", zh: "Denarixx" },
  "whatis.p1": { en: "Denarixx AI & Digital Solutions helps businesses build modern websites, automation systems, AI workflows, and scalable digital products.", de: "Denarixx AI & Digital Solutions hilft Unternehmen dabei, moderne Websites, Automatisierungssysteme, KI-Workflows und skalierbare digitale Produkte zu entwickeln.", fr: "Denarixx AI & Digital Solutions aide les entreprises à créer des sites web modernes, des systèmes d'automatisation, des workflows IA et des produits numériques évolutifs.", es: "Denarixx AI & Digital Solutions ayuda a las empresas a crear sitios web modernos, sistemas de automatización, flujos de IA y productos digitales escalables.", it: "Denarixx AI & Digital Solutions aiuta le aziende a creare siti web moderni, sistemi di automazione, workflow IA e prodotti digitali scalabili.", pt: "A Denarixx AI & Digital Solutions ajuda empresas a criar websites modernos, sistemas de automação, fluxos de IA e produtos digitais escaláveis.", nl: "Denarixx AI & Digital Solutions helpt bedrijven moderne websites, automatiseringssystemen, AI-workflows en schaalbare digitale producten te bouwen.", tr: "Denarixx AI & Digital Solutions, işletmelerin modern web siteleri, otomasyon sistemleri, yapay zeka iş akışları ve ölçeklenebilir dijital ürünler oluşturmasına yardımcı olur.", ar: "تساعد Denarixx AI & Digital Solutions الشركات على بناء مواقع حديثة وأنظمة أتمتة وسير عمل بالذكاء الاصطناعي ومنتجات رقمية قابلة للتوسع.", zh: "Denarixx AI & Digital Solutions 帮助企业构建现代网站、自动化系统、AI 工作流和可扩展的数字产品。" },
  "whatis.p2": { en: "We turn ideas into practical digital systems that help brands grow, save time, and operate more effectively.", de: "Wir verwandeln Ideen in praktische digitale Systeme, die Marken beim Wachstum helfen, Zeit sparen und effizienter arbeiten lassen.", fr: "Nous transformons les idées en systèmes numériques concrets qui aident les marques à se développer, à gagner du temps et à mieux fonctionner.", es: "Convertimos ideas en sistemas digitales prácticos que ayudan a las marcas a crecer, ahorrar tiempo y operar de forma más eficiente.", it: "Trasformiamo le idee in sistemi digitali pratici che aiutano i brand a crescere, risparmiare tempo e operare in modo più efficace.", pt: "Transformamos ideias em sistemas digitais práticos que ajudam marcas a crescer, economizar tempo e operar melhor.", nl: "Wij zetten ideeën om in praktische digitale systemen die merken helpen groeien, tijd besparen en efficiënter werken.", tr: "Fikirleri, markaların büyümesine, zaman kazanmasına ve daha verimli çalışmasına yardımcı olan pratik dijital sistemlere dönüştürüyoruz.", ar: "نحوّل الأفكار إلى أنظمة رقمية عملية تساعد العلامات التجارية على النمو وتوفير الوقت والعمل بكفاءة أكبر.", zh: "我们将创意转化为实用的数字系统，帮助品牌增长、节省时间并更高效地运营。" },
