  "pwa.ios.hint": { en: "Tap the share button, then \"Add to Home Screen\"", de: "Tippen Sie auf Teilen, dann \"Zum Startbildschirm\"", fr: "Appuyez sur Partager, puis \"Sur l'\u00e9cran d'accueil\"", es: "Toca Compartir, luego \"A\u00f1adir a pantalla de inicio\"", it: "Tocca Condividi, poi \"Aggiungi a schermata Home\"", pt: "Toque em Compartilhar, depois \"Tela de In\u00edcio\"", nl: "Tik op Delen, dan \"Zet op beginscherm\"", tr: "Payla\u015f'a dokun, sonra \"Ana Ekrana Ekle\"", ar: "\u0627\u0636\u063A\u0637 \u0645\u0634\u0627\u0631\u0643\u0629\u060C \u062B\u0645 \"\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0629 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629\"", zh: "\u70B9\u51FB\u5206\u4EAB\uFF0C\u7136\u540E\"\u6DFB\u52A0\u5230\u4E3B\u5C4F\u5E55\"" },

